/**
 * Lấy Auth Token từ request (GET hoặc POST)
 */
function get_request_token() {
    if (!empty($_POST['token'])) {
        return trim((string)$_POST['token']);
    }
    if (!empty($_GET['key'])) {
        return trim((string)$_GET['key']);
    }
    if (!empty($_GET['token'])) {
        return trim((string)$_GET['token']);
    }
    return '';
}

/**
 * Kiểm tra tính hợp lệ của Auth Token (sử dụng so sánh an toàn hash_equals)
 */
function is_token_valid($input_token) {
    if (empty($input_token)) {
        return false;
    }
    return hash_equals(SETUP_AUTH_TOKEN, $input_token);
}

/**
 * Kiểm tra thời hạn hoạt động của trình cài đặt (TTL 24 giờ)
 */
function check_ttl_expiration() {
    $created_time = is_numeric(SETUP_GENERATED_AT) ? (int)SETUP_GENERATED_AT : @filemtime(__FILE__);
    if (!$created_time || $created_time <= 0) {
        $created_time = time();
    }
    $ttl_limit = 86400; // 24 giờ tính bằng giây
    $elapsed = time() - $created_time;
    return [
        'expired' => $elapsed > $ttl_limit,
        'remaining_seconds' => max(0, $ttl_limit - $elapsed),
        'created_at' => $created_time
    ];
}

/**
 * Kiểm tra cơ chế tự khóa (Self-Locking): Nếu website đã cài đặt và DB đã có dữ liệu -> Khóa vĩnh viễn
 */
function check_self_locking() {
    $config_file = __DIR__ . '/wp-config.php';
    if (!file_exists($config_file)) {
        return false;
    }

    $config_content = @file_get_contents($config_file);
    if (!$config_content) {
        return false;
    }

    preg_match("/define\s*\(\s*['\"]DB_NAME['\"]\s*,\s*['\"](.*?)['\"]\s*\)/", $config_content, $m_name);
    preg_match("/define\s*\(\s*['\"]DB_USER['\"]\s*,\s*['\"](.*?)['\"]\s*\)/", $config_content, $m_user);
    preg_match("/define\s*\(\s*['\"]DB_PASSWORD['\"]\s*,\s*['\"](.*?)['\"]\s*\)/", $config_content, $m_pass);
    preg_match("/define\s*\(\s*['\"]DB_HOST['\"]\s*,\s*['\"](.*?)['\"]\s*\)/", $config_content, $m_host);
    preg_match("/\\\$table_prefix\s*=\s*['\"](.*?)['\"]/", $config_content, $m_prefix);

    $db_name = $m_name[1] ?? '';
    $db_user = $m_user[1] ?? '';
    $db_pass = $m_pass[1] ?? '';
    $db_host = $m_host[1] ?? 'localhost';
    $prefix  = $m_prefix[1] ?? 'wp_';

    if (empty($db_name) || empty($db_user)) {
        return false;
    }

    try {
        $pdo = new PDO("mysql:host={$db_host};dbname={$db_name};charset=utf8mb4", $db_user, $db_pass, [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_SILENT,
            PDO::ATTR_TIMEOUT => 2
        ]);
        $stmt = $pdo->query("SELECT option_value FROM `{$prefix}options` WHERE option_name = 'siteurl' LIMIT 1");
        if ($stmt) {
            $siteurl = $stmt->fetchColumn();
            if (!empty($siteurl)) {
                return [
                    'locked' => true,
                    'siteurl' => $siteurl,
                    'dbname' => $db_name
                ];
            }
        }
    } catch (Throwable $e) {
        return false;
    }

    return false;
}

/**
 * Tự động phát hiện URL hiện tại của thư mục cài đặt
 */
function detect_current_url() {
    $is_https = (!empty($_SERVER['HTTPS']) && strtolower($_SERVER['HTTPS']) !== 'off')
        || (isset($_SERVER['SERVER_PORT']) && (int)$_SERVER['SERVER_PORT'] === 443)
        || (!empty($_SERVER['HTTP_X_FORWARDED_PROTO']) && strtolower($_SERVER['HTTP_X_FORWARDED_PROTO']) === 'https')
        || (!empty($_SERVER['HTTP_X_FORWARDED_SSL']) && strtolower($_SERVER['HTTP_X_FORWARDED_SSL']) === 'on');

    $protocol = $is_https ? 'https://' : 'http://';
    $host = $_SERVER['HTTP_HOST'] ?? 'localhost';

    $raw_script = $_SERVER['SCRIPT_NAME'] ?? '/setup.php';
    $script_dir = str_replace('\\', '/', dirname($raw_script));
    $clean_dir  = preg_replace('#/(wp-admin|wp-content|wp-includes).*$#', '', $script_dir);
    $clean_dir  = trim($clean_dir, '/');
    $site_path  = ($clean_dir === '' || $clean_dir === '.') ? '' : '/' . $clean_dir;

    return rtrim($protocol . $host . $site_path, '/');
}

/**
 * Tự hủy file setup.php an toàn với Fallback 3 tầng (Windows/Apache lock fallback)
 */
function perform_self_destruct() {
    $file = __FILE__;

    // Tầng 1: Thử xóa trực tiếp bằng unlink
    if (@unlink($file)) {
        return [
            'status' => 'success',
            'message' => 'Đã xóa file cài đặt setup.php thành công khỏi máy chủ!'
        ];
    }

    // Tầng 2: Ghi đè vô hiệu hóa và đổi tên (Fallback cho Windows do Apache giữ handle)
    $disabled_stub = "<?php\n/** Trình cài đặt đã bị vô hiệu hóa an toàn */\nhttp_response_code(404);\nexit('404 Not Found - Setup disabled.');\n";
    $overwritten = @file_put_contents($file, $disabled_stub) !== false;
    $renamed_path = $file . '.disabled.' . time();
    $renamed = @rename($file, $renamed_path);

    if ($renamed) {
        return [
            'status' => 'success',
            'message' => 'Đã vô hiệu hóa và đổi tên file setup.php thành ' . basename($renamed_path) . ' thành công!'
        ];
    }

    if ($overwritten) {
        return [
            'status' => 'warning',
            'message' => 'Nội dung file setup.php đã được ghi đè vô hiệu hóa an toàn. Vui lòng xóa file thủ công khi thuận tiện.'
        ];
    }

    // Tầng 3: Cảnh báo xóa tay bắt buộc
    return [
        'status' => 'danger',
        'message' => 'Máy chủ không cho phép tự động xóa hoặc ghi đè file. BẠN CẦN XÓA THỦ CÔNG FILE NÀY ĐỂ BẢO MẬT: ' . $file
    ];
}

/**
 * Kiểm tra xem chuỗi có phải dữ liệu PHP Serialized hay không
 */
function is_serialized_string_format($data) {
    if (!is_string($data)) {
        return false;
    }
    $data = trim($data);
    if ($data === 'N;') {
        return true;
    }
    if (strlen($data) < 4) {
        return false;
    }
    if ($data[1] !== ':') {
        return false;
    }
    $lastc = substr($data, -1);
    if ($lastc !== ';' && $lastc !== '}') {
        return false;
    }
    $token = $data[0];
    switch ($token) {
        case 's':
            if (substr($data, -2, 1) !== '"') {
                return false;
            }
        case 'a':
        case 'O':
        case 'b':
        case 'i':
        case 'd':
            return (bool)preg_match("/^{$token}:[0-9]+:/s", $data);
    }
    return false;
}

/**
 * Thuật toán Safe Serialized Search & Replace (Đếm độ dài byte UTF-8 chuẩn xác)
 * Đảm bảo các cấu hình serialized của Flatsome UX Builder, WooCommerce, ACF không bị hỏng layout.
 */
function safe_replace_serialized_bytes($data, $search, $replace) {
    if (empty($search) || $search === $replace || !is_string($data) || strpos($data, $search) === false) {
        return $data;
    }

    // Nếu không phải định dạng serialized, thay thế chuỗi thông thường
    if (!is_serialized_string_format($data)) {
        return str_replace($search, $replace, $data);
    }

    $len = strlen($data);
    $result = '';
    $i = 0;

    while ($i < $len) {
        // Nhận diện cú pháp bắt đầu của chuỗi serialized: s:<length>:"
        if ($data[$i] === 's' && $i + 1 < $len && $data[$i + 1] === ':') {
            $colon_pos = strpos($data, ':', $i + 2);
            if ($colon_pos !== false && $colon_pos + 1 < $len && $data[$colon_pos + 1] === '"') {
                $num_str = substr($data, $i + 2, $colon_pos - ($i + 2));
                if (ctype_digit($num_str)) {
                    $str_len = (int)$num_str;
                    $str_start = $colon_pos + 2;
                    // Kiểm tra chuỗi kết thúc đúng với ";
                    if ($str_start + $str_len <= $len && substr($data, $str_start + $str_len, 2) === '";') {
                        $str_content = substr($data, $str_start, $str_len);
                        if (strpos($str_content, $search) !== false) {
                            $replaced_content = str_replace($search, $replace, $str_content);
                            $new_len = strlen($replaced_content); // Tính độ dài theo byte (chuẩn PHP serialize)
                            $result .= 's:' . $new_len . ':"' . $replaced_content . '";';
                        } else {
                            $result .= 's:' . $str_len . ':"' . $str_content . '";';
                        }
                        $i = $str_start + $str_len + 2;
                        continue;
                    }
                }
            }
        }

        $result .= $data[$i];
        $i++;
    }

    return $result;
}

/**
 * Thực thi file SQL nạp dữ liệu theo phương pháp Streaming (chống tràn RAM)
 */
function execute_sql_file($pdo, $sql_filepath) {
    if (!file_exists($sql_filepath)) {
        throw new Exception("Không tìm thấy file SQL cơ sở dữ liệu tại: " . htmlspecialchars($sql_filepath));
    }

    $handle = @fopen($sql_filepath, 'r');
    if (!$handle) {
        throw new Exception("Không thể mở file SQL để đọc. Vui lòng kiểm tra quyền truy cập file!");
    }

    // Tắt các ràng buộc để tăng tốc và tránh lỗi khóa ngoại khi import
    $pdo->exec("SET FOREIGN_KEY_CHECKS = 0;");
    $pdo->exec("SET UNIQUE_CHECKS = 0;");
    $pdo->exec("SET AUTOCOMMIT = 0;");

    $query = '';
    $in_string = false;
    $string_char = '';
    $escaped = false;
    $executed_count = 0;

    while (($line = fgets($handle)) !== false) {
        $trimmed_line = trim($line);

        // Bỏ qua dòng chú thích khi không nằm trong chuỗi
        if (!$in_string) {
            if ($trimmed_line === '' || strpos($trimmed_line, '--') === 0 || strpos($trimmed_line, '#') === 0) {
                continue;
            }
            if (strpos($trimmed_line, '/*') === 0 && substr($trimmed_line, -2) === '*/' && strpos($trimmed_line, '/*!') !== 0) {
                continue;
            }
        }

        $len = strlen($line);
        for ($i = 0; $i < $len; $i++) {
            $char = $line[$i];

            if ($escaped) {
                $escaped = false;
                $query .= $char;
                continue;
            }

            if ($char === '\\') {
                $escaped = true;
                $query .= $char;
                continue;
            }

            if ($in_string) {
                if ($char === $string_char) {
                    $in_string = false;
                }
                $query .= $char;
            } else {
                if ($char === "'" || $char === '"' || $char === '`') {
                    $in_string = true;
                    $string_char = $char;
                    $query .= $char;
                } elseif ($char === ';') {
                    $stmt = trim($query);
                    if ($stmt !== '') {
                        $pdo->exec($stmt);
                        $executed_count++;
                    }
                    $query = '';
                } else {
                    $query .= $char;
                }
            }
        }
    }

    $stmt = trim($query);
    if ($stmt !== '') {
        $pdo->exec($stmt);
        $executed_count++;
    }

    fclose($handle);

    // Bật lại các ràng buộc và xác nhận giao dịch
    $pdo->exec("COMMIT;");
    $pdo->exec("SET FOREIGN_KEY_CHECKS = 1;");
    $pdo->exec("SET UNIQUE_CHECKS = 1;");
    $pdo->exec("SET AUTOCOMMIT = 1;");

    return $executed_count;
}

/**
 * Cập nhật file wp-config.php (hoặc tạo mới từ wp-config-sample.php)
 */
function update_or_create_wp_config($db_name, $db_user, $db_pass, $db_host) {
    $config_file = __DIR__ . '/wp-config.php';
    $sample_file = __DIR__ . '/wp-config-sample.php';

    $content = '';
    if (file_exists($config_file)) {
        $content = file_get_contents($config_file);
    } elseif (file_exists($sample_file)) {
        $content = file_get_contents($sample_file);
    } else {
        throw new Exception("Không tìm thấy file wp-config.php hoặc wp-config-sample.php trong thư mục gốc!");
    }

    // Cập nhật thông số kết nối Database
    $content = preg_replace("/(define\s*\(\s*['\"]DB_NAME['\"]\s*,\s*['\"])(.*?)(['\"]\s*\);)/", "\${1}{$db_name}\${3}", $content);
    $content = preg_replace("/(define\s*\(\s*['\"]DB_USER['\"]\s*,\s*['\"])(.*?)(['\"]\s*\);)/", "\${1}{$db_user}\${3}", $content);
    $content = preg_replace("/(define\s*\(\s*['\"]DB_PASSWORD['\"]\s*,\s*['\"])(.*?)(['\"]\s*\);)/", "\${1}{$db_pass}\${3}", $content);
    $content = preg_replace("/(define\s*\(\s*['\"]DB_HOST['\"]\s*,\s*['\"])(.*?)(['\"]\s*\);)/", "\${1}{$db_host}\${3}", $content);

    // Chèn khối mã Dynamic URL nếu chưa có
    if (strpos($content, 'WP_HOME') === false && strpos($content, 'DYNAMIC_WP_URL') === false) {
        $dynamic_snippet = "\n// DYNAMIC_WP_URL: Tu dong nhan dien URL cho Localhost / Live Server\n"
            . "if (!defined('WP_HOME') || !defined('WP_SITEURL')) {\n"
            . "    if (php_sapi_name() !== 'cli' && isset(\$_SERVER['HTTP_HOST'])) {\n"
            . "        \$is_ssl = (!empty(\$_SERVER['HTTPS']) && strtolower(\$_SERVER['HTTPS']) !== 'off') || (isset(\$_SERVER['SERVER_PORT']) && (int)\$_SERVER['SERVER_PORT'] === 443);\n"
            . "        \$proto  = \$is_ssl ? 'https://' : 'http://';\n"
            . "        \$s_dir  = str_replace('\\\\', '/', dirname(\$_SERVER['SCRIPT_NAME'] ?? '/index.php'));\n"
            . "        \$clean  = trim(preg_replace('#/(wp-admin|wp-content|wp-includes).*$#', '', \$s_dir), '/');\n"
            . "        \$b_url  = rtrim(\$proto . \$_SERVER['HTTP_HOST'] . (\$clean === '' ? '' : '/' . \$clean), '/');\n"
            . "        if (!defined('WP_HOME')) define('WP_HOME', \$b_url);\n"
            . "        if (!defined('WP_SITEURL')) define('WP_SITEURL', \$b_url);\n"
            . "    }\n"
            . "}\n\n";

        if (strpos($content, "/* That's all, stop editing!") !== false) {
            $content = str_replace("/* That's all, stop editing!", $dynamic_snippet . "/* That's all, stop editing!", $content);
        } else {
            $content .= $dynamic_snippet;
        }
    }

    if (@file_put_contents($config_file, $content) === false) {
        throw new Exception("Không thể ghi file wp-config.php. Vui lòng cấp quyền ghi (Write Permission) cho thư mục website!");
    }
}

/**
 * Thực thi Search & Replace an toàn trên toàn bộ cơ sở dữ liệu
 */
function perform_database_search_replace($pdo, $prefix, $old_url, $new_url) {
    if (empty($old_url) || empty($new_url) || $old_url === $new_url) {
        return 0;
    }

    $affected_count = 0;

    // 1. Bảng Options
    $stmt = $pdo->prepare("SELECT option_id, option_value FROM `{$prefix}options` WHERE option_value LIKE :search");
    $stmt->execute([':search' => '%' . $old_url . '%']);
    $update_stmt = $pdo->prepare("UPDATE `{$prefix}options` SET option_value = :new_val WHERE option_id = :id");

    while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
        $new_val = safe_replace_serialized_bytes($row['option_value'], $old_url, $new_url);
        if ($new_val !== $row['option_value']) {
            $update_stmt->execute([':new_val' => $new_val, ':id' => $row['option_id']]);
            $affected_count++;
        }
    }

    // 2. Bảng Postmeta
    $stmt = $pdo->prepare("SELECT meta_id, meta_value FROM `{$prefix}postmeta` WHERE meta_value LIKE :search");
    $stmt->execute([':search' => '%' . $old_url . '%']);
    $update_stmt = $pdo->prepare("UPDATE `{$prefix}postmeta` SET meta_value = :new_val WHERE meta_id = :id");

    while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
        $new_val = safe_replace_serialized_bytes($row['meta_value'], $old_url, $new_url);
        if ($new_val !== $row['meta_value']) {
            $update_stmt->execute([':new_val' => $new_val, ':id' => $row['meta_id']]);
            $affected_count++;
        }
    }

    // 3. Bảng Posts
    $stmt = $pdo->prepare("SELECT ID, post_content, guid FROM `{$prefix}posts` WHERE post_content LIKE :search OR guid LIKE :search");
    $stmt->execute([':search' => '%' . $old_url . '%']);
    $update_stmt = $pdo->prepare("UPDATE `{$prefix}posts` SET post_content = :content, guid = :guid WHERE ID = :id");

    while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
        $new_content = safe_replace_serialized_bytes($row['post_content'], $old_url, $new_url);
        $new_guid = safe_replace_serialized_bytes($row['guid'], $old_url, $new_url);
        if ($new_content !== $row['post_content'] || $new_guid !== $row['guid']) {
            $update_stmt->execute([':content' => $new_content, ':guid' => $new_guid, ':id' => $row['ID']]);
            $affected_count++;
        }
    }

    return $affected_count;
}

