// ==============================================================================
// 4. LUỒNG ĐIỀU PHỐI VÀ XỬ LÝ CHÍNH
// ==============================================================================

if (defined('SETUP_TESTING_MODE') && SETUP_TESTING_MODE === true) {
    return;
}

$request_token = get_request_token();
$action = $_GET['action'] ?? $_POST['action'] ?? '';

// Xử lý tự hủy file nếu có yêu cầu
if ($action === 'self_destruct') {
    // Chỉ cho phép tự hủy nếu có token hợp lệ hoặc trang đã bị khóa
    $lock_info = check_self_locking();
    if (!is_token_valid($request_token) && !$lock_info) {
        http_response_code(403);
        $html = '<div class="alert alert-danger"><strong>403 Forbidden:</strong> Yêu cầu Khóa xác thực (Auth Token) hợp lệ để thực hiện thao tác tự hủy.</div>';
        render_html_layout('Từ Chối Truy Cập', $html, 'Lỗi Bảo Mật');
        exit;
    }

    $destruct_result = perform_self_destruct();
    $alert_class = 'alert-' . ($destruct_result['status'] === 'success' ? 'success' : ($destruct_result['status'] === 'warning' ? 'warning' : 'danger'));

    $html = '<div class="alert ' . $alert_class . '"><strong>' . htmlspecialchars($destruct_result['message']) . '</strong></div>';
    $html .= '<p style="margin-bottom: 20px; font-size: 14px; color: var(--text-muted);">Trình cài đặt setup.php đã được xử lý an toàn nhằm loại bỏ hoàn toàn các rủi ro bảo mật cho website của bạn.</p>';
    $html .= '<a href="' . htmlspecialchars(detect_current_url()) . '/wp-admin/" class="btn btn-primary">Đăng Nhập Quản Trị WP-Admin</a>';

    render_html_layout('Tự Hủy Trình Cài Đặt', $html, 'Bảo Mật Hệ Thống');
    exit;
}

// --- LAYER 1: KIỂM TRA AUTH TOKEN ---
if (!is_token_valid($request_token)) {
    http_response_code(403);
    $error_msg = !empty($request_token) ? 'Khóa xác thực (Auth Token) không chính xác. Vui lòng kiểm tra lại!' : '';

    $html = '';
    if (!empty($error_msg)) {
        $html .= '<div class="alert alert-danger"><strong>403 Forbidden:</strong> ' . htmlspecialchars($error_msg) . '</div>';
    } else {
        $html .= '<div class="alert alert-info"><strong>Yêu Cầu Xác Thực:</strong> Để bảo vệ an toàn cho website, trình cài đặt yêu cầu <strong>Khóa xác thực (Auth Token)</strong> được cấp trong báo cáo đóng gói dự án.</div>';
    }

    $html .= '<form method="GET" action="">';
    $html .= '  <div class="form-group">';
    $html .= '    <label for="input_key">Nhập Auth Token</label>';
    $html .= '    <input type="text" id="input_key" name="key" class="form-control" placeholder="Ví dụ: a1b2c3d4e5f6..." required autofocus>';
    $html .= '    <div class="hint">Khóa này được sinh tự động khi chạy lệnh đóng gói dự án.</div>';
    $html .= '  </div>';
    $html .= '  <button type="submit" class="btn btn-primary">Xác Thực & Mở Khóa Trình Cài Đặt</button>';
    $html .= '</form>';

    render_html_layout('Xác Thực Quyền Truy Cập', $html, 'Cơ Chế Bảo Mật Lớp 1');
    exit;
}

// --- LAYER 2: KIỂM TRA THỜI GIAN HOẠT ĐỘNG (TTL 24H) ---
$ttl_info = check_ttl_expiration();
if ($ttl_info['expired']) {
    http_response_code(403);
    $html = '<div class="alert alert-danger"><strong>Khóa Cài Đặt Đã Hết Hạn:</strong> File setup.php này đã vượt quá thời hạn sử dụng an toàn (24 giờ kể từ thời điểm tạo). Trình cài đặt đã tự động khóa vĩnh viễn để bảo vệ máy chủ.</div>';
    $html .= '<p style="margin-bottom: 24px; font-size: 14px; color: var(--text-muted);">Vui lòng thực hiện lại quy trình đóng gói dự án để sinh mã token mới, hoặc xóa file này ngay lập tức.</p>';
    $html .= '<a href="?action=self_destruct&token=' . urlencode($request_token) . '" class="btn btn-danger" onclick="return confirm(\'Bạn có chắc chắn muốn xóa file này không?\');">Xóa Ngay File setup.php Này</a>';

    render_html_layout('Trình Cài Đặt Đã Hết Hạn', $html, 'Cơ Chế Bảo Mật Lớp 2 (TTL)');
    exit;
}

// --- LAYER 3: KIỂM TRA TỰ KHÓA (SELF-LOCKING / ANTI-REPLAY) ---
$lock_status = check_self_locking();
if ($lock_status && $lock_status['locked']) {
    http_response_code(403);
    $html = '<div class="alert alert-warning"><strong>Website Đã Được Cài Đặt:</strong> Cơ sở dữ liệu <code>' . htmlspecialchars($lock_status['dbname']) . '</code> đã được kết nối và cấu hình hoàn tất cho tên miền <code>' . htmlspecialchars($lock_status['siteurl']) . '</code>.</div>';
    $html .= '<p style="margin-bottom: 20px; font-size: 14px; color: var(--text-muted);">Trình cài đặt <code>setup.php</code> đã tự động kích hoạt tính năng Tự Khóa (Self-Locking) để ngăn chặn các cuộc tấn công ghi đè hoặc nạp lại dữ liệu (Anti-Replay Attack).</p>';
    $html .= '<div style="display: flex; gap: 12px; margin-bottom: 16px;">';
    $html .= '  <a href="' . htmlspecialchars($lock_status['siteurl']) . '" class="btn btn-secondary" target="_blank">Xem Trang Chủ</a>';
    $html .= '  <a href="' . htmlspecialchars($lock_status['siteurl']) . '/wp-admin/" class="btn btn-primary" target="_blank">Vào Quản Trị WP-Admin</a>';
    $html .= '</div>';
    $html .= '<a href="?action=self_destruct&token=' . urlencode($request_token) . '" class="btn btn-danger" onclick="return confirm(\'Bạn có chắc chắn muốn xóa file setup.php này để bảo vệ website?\');">Tự Hủy File setup.php Ngay (Khuyến Nghị)</a>';

    render_html_layout('Trình Cài Đặt Đã Tự Động Khóa', $html, 'Cơ Chế Bảo Mật Lớp 3 (Self-Locking)');
    exit;
}

// --- XỬ LÝ THỰC THI CÀI ĐẶT (KHI SUBMIT FORM) ---
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($action === 'do_install')) {
    $db_host = trim($_POST['db_host'] ?? 'localhost');
    $db_name = trim($_POST['db_name'] ?? '');
    $db_user = trim($_POST['db_user'] ?? 'root');
    $db_pass = trim($_POST['db_pass'] ?? '');
    $site_url = rtrim(trim($_POST['site_url'] ?? detect_current_url()), '/');
    $sql_filename = trim($_POST['sql_file'] ?? SETUP_SQL_FILE);

    $errors = [];
    if (empty($db_name)) {
        $errors[] = 'Vui lòng nhập tên Database!';
    }
    if (empty($db_user)) {
        $errors[] = 'Vui lòng nhập tên người dùng Database!';
    }

    $sql_path = __DIR__ . '/' . $sql_filename;
    if (!file_exists($sql_path)) {
        // Thử tìm file sql bất kỳ trong thư mục
        $glob_sqls = glob(__DIR__ . '/*.sql');
        if (!empty($glob_sqls)) {
            $sql_path = $glob_sqls[0];
            $sql_filename = basename($sql_path);
        } else {
            $errors[] = 'Không tìm thấy file SQL cơ sở dữ liệu: ' . htmlspecialchars($sql_filename);
        }
    }

    if (empty($errors)) {
        try {
            // 1. Kết nối MySQL Server và tạo Database nếu chưa có
            $pdo_init = new PDO("mysql:host={$db_host};charset=utf8mb4", $db_user, $db_pass, [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_TIMEOUT => 5
            ]);
            $pdo_init->exec("CREATE DATABASE IF NOT EXISTS `{$db_name}` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");
            unset($pdo_init);

            // 2. Kết nối trực tiếp vào Database đã chọn
            $pdo = new PDO("mysql:host={$db_host};dbname={$db_name};charset=utf8mb4", $db_user, $db_pass, [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION
            ]);

            // 3. Thực thi nạp file SQL
            $executed_queries = execute_sql_file($pdo, $sql_path);

            // 4. Nhận diện prefix bảng WordPress
            $tables_stmt = $pdo->query("SHOW TABLES LIKE '%options'");
            $tables = $tables_stmt->fetchAll(PDO::FETCH_COLUMN);
            $prefix = 'wp_';
            if (!empty($tables)) {
                if (preg_match('/^(.*?)options$/', $tables[0], $pm)) {
                    $prefix = $pm[1];
                }
            }

            // 5. Lấy URL cũ từ cơ sở dữ liệu vừa import
            $old_url_stmt = $pdo->query("SELECT option_value FROM `{$prefix}options` WHERE option_name = 'siteurl' LIMIT 1");
            $old_url = $old_url_stmt ? rtrim((string)$old_url_stmt->fetchColumn(), '/') : '';

            // 6. Thực thi Safe Serialized Search & Replace
            $replaced_rows = 0;
            if (!empty($old_url) && $old_url !== $site_url) {
                $replaced_rows = perform_database_search_replace($pdo, $prefix, $old_url, $site_url);
            }

            // 7. Cập nhật wp-config.php
            update_or_create_wp_config($db_name, $db_user, $db_pass, $db_host);

            // 8. Hiển thị màn hình thành công
            $html = '<div class="alert alert-success"><strong>Cài đặt hoàn tất thành công!</strong> Website của bạn đã sẵn sàng hoạt động ngay lập tức.</div>';
            
            $html .= '<div class="card-box">';
            $html .= '  <div class="card-box-title">Thống Kê Khôi Phục Hệ Thống</div>';
            $html .= '  <div class="creds-row"><span class="creds-label">Cơ sở dữ liệu:</span><span class="creds-value">' . htmlspecialchars($db_name) . '</span></div>';
            $html .= '  <div class="creds-row"><span class="creds-label">Câu lệnh SQL đã nạp:</span><span class="creds-value">' . number_format($executed_queries) . ' truy vấn</span></div>';
            $html .= '  <div class="creds-row"><span class="creds-label">URL Cũ -> Mới:</span><span class="creds-value">' . htmlspecialchars($old_url ?: 'N/A') . ' &rarr; ' . htmlspecialchars($site_url) . '</span></div>';
            $html .= '  <div class="creds-row"><span class="creds-label">Dữ liệu Serialized cập nhật:</span><span class="creds-value">' . number_format($replaced_rows) . ' bản ghi an toàn</span></div>';
            $html .= '</div>';

            $html .= '<div class="card-box" style="border-left: 4px solid var(--primary);">';
            $html .= '  <div class="card-box-title">Thông Tin Quản Trị Mặc Định</div>';
            $html .= '  <div class="creds-row"><span class="creds-label">Tài khoản Admin:</span><span class="creds-value">admin</span></div>';
            $html .= '  <div class="creds-row"><span class="creds-label">Mật khẩu:</span><span class="creds-value">adminpassword123</span></div>';
            $html .= '  <div class="creds-row"><span class="creds-label">Trang Quản Trị:</span><span class="creds-value"><a href="' . htmlspecialchars($site_url) . '/wp-admin/" target="_blank">' . htmlspecialchars($site_url) . '/wp-admin/</a></span></div>';
            $html .= '</div>';

            $html .= '<div style="margin-bottom: 24px;">';
            $html .= '  <a href="?action=self_destruct&token=' . urlencode($request_token) . '" class="btn btn-danger" onclick="return confirm(\'Hành động này sẽ xóa file setup.php để ngăn người khác cài đặt lại. Bạn có chắc chắn?\');">';
            $html .= '    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path></svg>';
            $html .= '    TỰ HỦY FILE SETUP.PHP NGAY BÂY GIỜ (Khuyến Nghị Bắt Buộc)';
            $html .= '  </a>';
            $html .= '</div>';

            $html .= '<div style="display: flex; gap: 12px;">';
            $html .= '  <a href="' . htmlspecialchars($site_url) . '" class="btn btn-secondary" target="_blank">Xem Website</a>';
            $html .= '  <a href="' . htmlspecialchars($site_url) . '/wp-admin/" class="btn btn-primary" target="_blank">Đăng Nhập WP-Admin</a>';
            $html .= '</div>';

            render_html_layout('Cài Đặt Thành Công', $html, 'Khôi Phục Hoàn Tất');
            exit;

        } catch (Throwable $e) {
            $errors[] = 'Lỗi thực thi MySQL: ' . $e->getMessage();
        }
    }

    if (!empty($errors)) {
        $error_html = '<div class="alert alert-danger"><strong>Đã xảy ra lỗi:</strong><ul style="margin-left: 20px; margin-top: 6px;">';
        foreach ($errors as $err) {
            $error_html .= '<li>' . htmlspecialchars($err) . '</li>';
        }
        $error_html .= '</ul></div>';
    }
}

// --- HIỂN THỊ FORM CẤU HÌNH THÔNG SỐ CÀI ĐẶT ---
$detected_url = detect_current_url();
$default_db_name = SETUP_DEFAULT_DB !== '' ? SETUP_DEFAULT_DB : 'wordpress';
$default_sql_file = SETUP_SQL_FILE !== '' ? SETUP_SQL_FILE : 'database.sql';

$html = '';
